"""Deterministic, rule-based learning insights (Vietnamese). NOT generated by an LLM.

Every insight cites the measured numbers it was derived from (``evidence``) and uses
cautious wording ("có thể", "dấu hiệu") because small datasets make metrics noisy.
"""
from __future__ import annotations

from typing import Any


def _ins(id_: str, severity: str, title: str, message: str, evidence: dict[str, Any], lesson: str | None = None) -> dict[str, Any]:
    return {"id": id_, "severity": severity, "title": title, "message": message, "evidence": evidence, "lesson": lesson}


def _pct(x: float) -> str:
    return f"{x * 100:.0f}%"


def generate_insights(
    epochs: list[dict[str, Any]],
    config: dict[str, Any] | None = None,
    dataset_summary: dict[str, Any] | None = None,
    evaluation: dict[str, Any] | None = None,
    finished: bool = True,
) -> list[dict[str, Any]]:
    cfg = config or {}
    out: list[dict[str, Any]] = []
    n = len(epochs)

    # ---------------------------------------------------------------- dataset-level
    if dataset_summary:
        pcs = dataset_summary.get("per_class", [])
        trains = [c["train"] for c in pcs if c.get("total", 0) > 0]
        if trains:
            if min(trains) < 20:
                out.append(_ins(
                    "small_dataset", "warning", "Tập dữ liệu nhỏ",
                    f"Class ít ảnh nhất chỉ có {min(trains)} ảnh train. Với ít ảnh, kết quả có thể thay đổi nhiều giữa các lần huấn luyện và validation accuracy kém ổn định. "
                    "Thêm ảnh đa dạng (góc nhìn, ánh sáng, nền) thường hữu ích hơn tăng số epoch.",
                    {"min_train_per_class": min(trains)}, "dataset"))
            if min(trains) > 0 and max(trains) / min(trains) >= 2:
                out.append(_ins(
                    "class_imbalance", "warning", "Các class không cân bằng",
                    f"Class nhiều ảnh nhất gấp {max(trains) / min(trains):.1f} lần class ít ảnh nhất. Mô hình có thể thiên về class phổ biến; hãy xem recall từng class thay vì chỉ nhìn accuracy tổng.",
                    {"train_counts": trains}, "dataset"))
        if dataset_summary.get("split", {}).get("strategy") == "random":
            out.append(_ins(
                "random_split_caveat", "info", "Validation được chia ngẫu nhiên từ cùng dữ liệu",
                "Nếu ảnh được chụp liên tiếp, ảnh validation có thể rất giống ảnh train nên validation accuracy có thể lạc quan hơn thực tế. Hãy thử chụp một phiên riêng làm validation.",
                {}, "overfitting"))

    if n == 0:
        return out

    last = epochs[-1]
    tl = [e["train_loss"] for e in epochs]
    vl = [e["val_loss"] for e in epochs]
    ta = [e["train_accuracy"] for e in epochs]
    va = [e["val_accuracy"] for e in epochs]
    best_i = max(range(n), key=lambda i: (va[i], -vl[i]))

    # ---------------------------------------------------------------- loss decreasing
    if n >= 2 and tl[-1] < tl[0] * 0.8:
        out.append(_ins(
            "train_loss_decreasing", "success", "Training loss đang giảm",
            f"Training loss giảm từ {tl[0]:.3f} xuống {tl[-1]:.3f}: mô hình đang khớp dần với dữ liệu train. Hãy so sánh với validation loss để biết nó có học được điều tổng quát hay không.",
            {"first": tl[0], "last": tl[-1]}, "epoch"))

    # ---------------------------------------------------------------- overfitting
    gap = ta[-1] - va[-1]
    recent = vl[-3:] if n >= 3 else []
    val_loss_rising = len(recent) == 3 and recent[0] < recent[1] < recent[2]
    train_improving = n >= 3 and ta[-1] >= ta[-3] - 1e-9 and tl[-1] <= tl[-3] + 1e-9
    if n >= 3 and val_loss_rising and train_improving:
        out.append(_ins(
            "val_loss_rising", "warning", "Validation loss đang tăng trong khi training tốt lên",
            "Training accuracy đang cải thiện nhưng validation loss tăng liên tục. Đây có thể là dấu hiệu overfitting. "
            "Hãy thử thêm ảnh độc lập, bật data augmentation, tăng dropout/weight decay, giảm độ phức tạp mô hình hoặc dùng early stopping.",
            {"val_loss_last3": recent, "train_acc": ta[-1]}, "overfitting"))
    if n >= 3 and gap >= 0.15 and ta[-1] >= 0.8:
        out.append(_ins(
            "overfitting_gap", "warning", "Training accuracy cao nhưng validation accuracy thấp hơn nhiều",
            f"Train {_pct(ta[-1])} so với validation {_pct(va[-1])} (chênh {_pct(gap)}). Có thể mô hình đang ghi nhớ ảnh train thay vì học đặc trưng tổng quát (overfitting), nhưng với validation nhỏ hãy kiểm tra lại bằng thêm dữ liệu.",
            {"train_accuracy": ta[-1], "val_accuracy": va[-1]}, "overfitting"))
    if n >= 4 and best_i < n - 3 and vl[-1] > min(vl) * 1.15:
        out.append(_ins(
            "past_best_epoch", "info", "Epoch tốt nhất đã qua từ lâu",
            f"Kết quả validation tốt nhất ở epoch {best_i + 1}, các epoch sau không cải thiện. Hệ thống đã lưu checkpoint của epoch đó. Nhiều epoch hơn không đảm bảo mô hình tốt hơn.",
            {"best_epoch": best_i + 1, "epochs": n}, "epoch"))

    # ---------------------------------------------------------------- underfitting / low accuracy
    if finished and n >= 3 and ta[-1] < 0.6 and va[-1] < 0.6:
        out.append(_ins(
            "underfitting", "warning", "Mô hình có thể chưa học đủ (underfitting)",
            f"Cả train ({_pct(ta[-1])}) và validation ({_pct(va[-1])}) đều thấp. Có thể cần thêm epoch, learning rate khác, thêm neuron/lớp ẩn hoặc dữ liệu rõ ràng hơn. Cũng cần kiểm tra các class có thật sự khác nhau về hình ảnh.",
            {"train_accuracy": ta[-1], "val_accuracy": va[-1]}, "epoch"))
    elif finished and va[-1] < 0.7 and not (n >= 3 and ta[-1] < 0.6):
        out.append(_ins(
            "low_val_accuracy", "warning", "Validation accuracy còn thấp",
            f"Validation accuracy hiện là {_pct(va[-1])}. Hãy xem confusion matrix để biết các class nào bị nhầm lẫn và bổ sung ảnh đa dạng cho các class đó.",
            {"val_accuracy": va[-1]}, "confusion"))
    if finished and n >= 3 and va[-1] >= 0.99 and (dataset_summary or {}).get("split", {}).get("val", 99) < 20:
        out.append(_ins(
            "perfect_small_val", "info", "100% trên tập validation nhỏ chưa chắc là mô hình tốt",
            "Khi validation chỉ có ít ảnh, một kết quả hoàn hảo có thể do may mắn hoặc do ảnh quá giống ảnh train. Hãy thử với ảnh mới hoàn toàn trong Live Inference.",
            {"val_accuracy": va[-1]}, "overfitting"))

    # ---------------------------------------------------------------- instability / learning rate
    if n >= 4:
        jumps = sum(1 for i in range(1, n) if tl[i] > tl[i - 1] * 1.2)
        va_delta = sum(abs(va[i] - va[i - 1]) for i in range(1, n)) / (n - 1)
        unstable = jumps >= max(2, (n - 1) // 3) or va_delta > 0.15
        if unstable:
            out.append(_ins(
                "unstable_training", "warning", "Quá trình huấn luyện dao động",
                "Loss/accuracy dao động mạnh giữa các epoch. Nguyên nhân có thể là learning rate hơi lớn, batch size nhỏ hoặc validation quá ít ảnh. Hãy thử giảm learning rate hoặc tăng batch size.",
                {"train_loss_spikes": jumps, "mean_abs_val_acc_change": round(va_delta, 3)}, "learning_rate"))
            lr = cfg.get("learning_rate")
            opt = cfg.get("optimizer", "adam")
            if lr is not None and ((opt == "adam" and lr >= 0.01) or (opt == "sgd" and lr >= 0.05)):
                out.append(_ins(
                    "lr_maybe_high", "warning", "Learning rate có thể đang quá cao",
                    f"Learning rate {lr:g} với {opt.upper()} khá lớn và loss đang dao động. Hãy thử giá trị nhỏ hơn (ví dụ 10 lần nhỏ hơn) để xem đường loss có mượt hơn không.",
                    {"learning_rate": lr, "optimizer": opt}, "learning_rate"))

    if n >= 3 and tl[-1] > tl[0]:
        out.append(_ins(
            "train_loss_not_decreasing", "warning", "Training loss không giảm",
            f"Training loss cuối ({tl[-1]:.3f}) không thấp hơn ban đầu ({tl[0]:.3f}). Learning rate có thể không phù hợp hoặc dữ liệu/nhãn có vấn đề.",
            {"first": tl[0], "last": tl[-1]}, "learning_rate"))

    # ---------------------------------------------------------------- evaluation-based
    val_report = (evaluation or {}).get("validation") if evaluation else None
    if val_report and val_report.get("per_class"):
        weak = [c for c in val_report["per_class"] if c["support"] > 0 and c["recall"] < 0.6]
        if weak and val_report.get("accuracy", 0) >= 0.5:
            names = ", ".join(f"“{c['label']}” (recall {_pct(c['recall'])})" for c in weak)
            out.append(_ins(
                "weak_class", "warning", "Có class bị nhận diện kém",
                f"Mô hình bỏ sót nhiều ảnh thuộc {names}. Hãy thêm ảnh đa dạng cho class này hoặc kiểm tra xem nó có dễ nhầm với class khác không.",
                {"classes": [c["label"] for c in weak]}, "confusion"))
        if val_report.get("mean_confidence_wrong") and val_report["mean_confidence_wrong"] > 0.8:
            out.append(_ins(
                "confident_mistakes", "info", "Mô hình có thể sai nhưng rất tự tin",
                f"Các ảnh bị nhận sai có độ tin cậy trung bình {_pct(val_report['mean_confidence_wrong'])}. Độ tin cậy cao không có nghĩa là dự đoán đúng.",
                {"mean_confidence_wrong": val_report["mean_confidence_wrong"]}, "confusion"))
    if not out:
        out.append(_ins("no_issue", "info", "Chưa phát hiện vấn đề rõ ràng",
                        "Các chỉ số hiện tại chưa kích hoạt cảnh báo nào. Hãy thử với ảnh mới trong Live Inference và thử thay đổi một tham số để so sánh.",
                        {}, None))
    return out
